const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});
const now=()=>new Date().toISOString();
const priorities=new Set(["منخفضة","عادية","مهمة","عاجلة","حرجة"]),types=new Set(["وارد","صادر","داخلي"]),statuses=new Set(["جديدة","قيد الإجراء","بانتظار الرد","متأخرة","مكتملة","مغلقة"]);
const user=req=>({id:req.headers.get("oai-authenticated-user-id")||(new URL(req.url).hostname==="localhost"?"local-user":null),email:req.headers.get("oai-authenticated-user-email")});
const ip=req=>req.headers.get("cf-connecting-ip")||req.headers.get("x-forwarded-for")||"غير متاح";
function addWorkDays(start,days){const d=new Date(start);let left=Math.max(1,Number(days)||3);while(left){d.setUTCDate(d.getUTCDate()+1);if(![5,6].includes(d.getUTCDay()))left--}return d.toISOString()}
async function parse(req){try{return await req.json()}catch{return null}}
async function audit(env,req,action,type,id,details={}){const u=user(req);await env.DB.prepare("INSERT INTO audit_logs (user_id,user_email,action,resource_type,resource_id,details,ip_address,created_at) VALUES (?,?,?,?,?,?,?,?)").bind(u.id||"anonymous",u.email,action,type,String(id||""),JSON.stringify(details),ip(req),now()).run()}
async function seed(env){const n=await env.DB.prepare("SELECT COUNT(*) total FROM transactions").first();if(Number(n?.total))return;const t=now(),due=addWorkDays(t,3);const rows=[["و-1448-0187","وارد","حرجة","دعوة للمشاركة في معرض رداء","جمعية الزاد للخدمات الإنسانية","الإدارة التنفيذية","متأخرة","بانتظار اعتماد الرد"],["و-1448-0182","وارد","عاجلة","طلب بيانات المستفيدين للربع الثالث","وزارة الموارد البشرية","خدمات المستفيدين","قيد الإجراء",null],["ص-1448-0096","صادر","مهمة","تقرير إنجاز مشروع السلة الغذائية","مؤسسة مانحة","الشراكات","متأخرة","نقص مرفق التقرير المالي"]];for(const r of rows)await env.DB.prepare("INSERT INTO transactions (reference,type,priority,subject,entity,department,status,sla_days,due_at,delay_reason,created_at,updated_at,created_by) VALUES (?,?,?,?,?,?,?,3,?,?,?,?,?)").bind(...r.slice(0,7),due,r[7],t,t,"system").run()}
async function detail(env,id){const t=await env.DB.prepare("SELECT * FROM transactions WHERE id=?").bind(id).first();if(!t)return null;const [e,c,a]=await Promise.all([env.DB.prepare("SELECT * FROM transaction_events WHERE transaction_id=? ORDER BY created_at").bind(id).all(),env.DB.prepare("SELECT * FROM comments WHERE transaction_id=? ORDER BY created_at DESC").bind(id).all(),env.DB.prepare("SELECT id,filename,content_type,size_bytes,created_at FROM attachments WHERE transaction_id=?").bind(id).all()]);return{...t,events:e.results,comments:c.results,attachments:a.results}}
async function list(env,url){let sql="SELECT * FROM transactions WHERE 1=1",b=[];const q=url.searchParams.get("q"),filters=[["type","type"],["status","status"],["priority","priority"],["department","department"]];if(q){sql+=" AND (reference LIKE ? OR subject LIKE ? OR entity LIKE ? OR identity_number LIKE ?)";b.push(...Array(4).fill(`%${q}%`))}for(const [param,col] of filters){const v=url.searchParams.get(param);if(v){sql+=` AND ${col}=?`;b.push(v)}}sql+=" ORDER BY CASE priority WHEN 'حرجة' THEN 1 WHEN 'عاجلة' THEN 2 WHEN 'مهمة' THEN 3 WHEN 'عادية' THEN 4 ELSE 5 END, created_at DESC";return(await env.DB.prepare(sql).bind(...b).all()).results}
async function api(req,env,url){
 await seed(env);const path=url.pathname,method=req.method,u=user(req);
 if(path==="/api/health")return json({ok:true,service:"morasalat-api",database:"connected",time:now()});
 if(path==="/api/metrics"){const rows=(await env.DB.prepare("SELECT type,status,COUNT(*) total FROM transactions GROUP BY type,status").all()).results;return json({ok:true,rows})}
 if(path==="/api/transactions"&&method==="GET")return json({ok:true,data:await list(env,url)});
 if(path==="/api/transactions"&&method==="POST"){if(!u.id)return json({ok:false,error:"يلزم تسجيل الدخول"},401);const b=await parse(req);if(!b||!types.has(b.type)||!priorities.has(b.priority)||!b.subject?.trim()||!b.entity?.trim()||!b.department?.trim())return json({ok:false,error:"تحقق من الحقول المطلوبة"},422);if(b.identity_number&&(!/^[12][0-9]{9}$/.test(b.identity_number)||b.type!=="وارد"))return json({ok:false,error:"رقم الهوية غير صحيح"},422);const t=now(),sla=Math.min(30,Math.max(1,Number(b.sla_days)||3)),temp=`TMP-${crypto.randomUUID()}`;const r=await env.DB.prepare("INSERT INTO transactions (reference,type,priority,subject,entity,identity_number,department,status,sla_days,due_at,created_at,updated_at,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(temp,b.type,b.priority,b.subject.trim(),b.entity.trim(),b.identity_number||null,b.department.trim(),"جديدة",sla,addWorkDays(t,sla),t,t,u.id).run();const id=r.meta.last_row_id,reference=`${b.type[0]}-${new Date().getUTCFullYear()}-${String(id).padStart(4,"0")}`;await env.DB.batch([env.DB.prepare("UPDATE transactions SET reference=? WHERE id=?").bind(reference,id),env.DB.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"تسجيل المعاملة","تم إنشاء المعاملة",b.department,u.email||u.id,t)]);await audit(env,req,"create","transaction",id,{reference});return json({ok:true,data:await detail(env,id)},201)}
 const m=path.match(/^\/api\/transactions\/(\d+)(?:\/(transfer|comments|attachments))?$/);if(m){const id=Number(m[1]),action=m[2];if(method==="GET"&&!action){const d=await detail(env,id);return d?json({ok:true,data:d}):json({ok:false,error:"المعاملة غير موجودة"},404)}if(!u.id)return json({ok:false,error:"يلزم تسجيل الدخول"},401);
  if(method==="PATCH"&&!action){const b=await parse(req),parts=[],vals=[];for(const [k,col,set] of [["status","status",statuses],["priority","priority",priorities],["subject","subject"],["entity","entity"],["delay_reason","delay_reason"]])if(b?.[k]!==undefined&&(!set||set.has(b[k]))){parts.push(`${col}=?`);vals.push(b[k])}if(!parts.length)return json({ok:false,error:"لا توجد تغييرات"},422);parts.push("updated_at=?");vals.push(now(),id);await env.DB.prepare(`UPDATE transactions SET ${parts.join(",")} WHERE id=?`).bind(...vals).run();await audit(env,req,"update","transaction",id,b);return json({ok:true,data:await detail(env,id)})}
  if(method==="POST"&&action==="transfer"){const b=await parse(req);if(!b?.department?.trim())return json({ok:false,error:"حدد الإدارة"},422);const t=now();await env.DB.batch([env.DB.prepare("UPDATE transactions SET department=?,status='قيد الإجراء',due_at=?,updated_at=? WHERE id=?").bind(b.department,addWorkDays(t,b.sla_days||3),t,id),env.DB.prepare("INSERT INTO transaction_events (transaction_id,action,details,department,actor,created_at) VALUES (?,?,?,?,?,?)").bind(id,"تحويل المعاملة",b.note||"تم التحويل",b.department,u.email||u.id,t)]);await audit(env,req,"transfer","transaction",id,b);return json({ok:true,data:await detail(env,id)})}
  if(method==="POST"&&action==="comments"){const b=await parse(req);if(!b?.body?.trim())return json({ok:false,error:"اكتب الملاحظة"},422);await env.DB.prepare("INSERT INTO comments (transaction_id,body,author,created_at) VALUES (?,?,?,?)").bind(id,b.body.trim(),u.email||u.id,now()).run();await audit(env,req,"comment","transaction",id);return json({ok:true,data:await detail(env,id)},201)}
  if(method==="POST"&&action==="attachments"){const form=await req.formData(),file=form.get("file");if(!(file instanceof File)||file.size>10485760)return json({ok:false,error:"الملف مطلوب وبحد أقصى 10MB"},422);const key=`transactions/${id}/${crypto.randomUUID()}-${file.name.replace(/[^\p{L}\p{N}._-]/gu,"_")}`;await env.BUCKET.put(key,file.stream(),{httpMetadata:{contentType:file.type||"application/octet-stream"}});await env.DB.prepare("INSERT INTO attachments (transaction_id,object_key,filename,content_type,size_bytes,uploaded_by,created_at) VALUES (?,?,?,?,?,?,?)").bind(id,key,file.name,file.type||"application/octet-stream",file.size,u.email||u.id,now()).run();await audit(env,req,"upload","attachment",id,{filename:file.name});return json({ok:true,data:await detail(env,id)},201)}
 }
 if(path==="/api/templates"&&method==="GET")return json({ok:true,data:(await env.DB.prepare("SELECT * FROM letter_templates ORDER BY updated_at DESC").all()).results});
 if(path==="/api/templates"&&method==="POST"){if(!u.id)return json({ok:false,error:"يلزم تسجيل الدخول"},401);const b=await parse(req);if(!b?.name?.trim()||!b?.body?.trim())return json({ok:false,error:"الاسم والمحتوى مطلوبان"},422);const t=now(),r=await env.DB.prepare("INSERT INTO letter_templates (name,category,body,created_at,updated_at) VALUES (?,?,?,?,?)").bind(b.name.trim(),b.category||"عام",b.body.trim(),t,t).run();await audit(env,req,"create","template",r.meta.last_row_id);return json({ok:true,id:r.meta.last_row_id},201)}
 if(path==="/api/audit")return json({ok:true,data:(await env.DB.prepare("SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT 100").all()).results});
 if(path==="/api/reports/transactions.csv"){const rows=await list(env,url),esc=v=>`"${String(v??"").replaceAll('"','""')}"`,csv=["الرقم,النوع,الأولوية,الموضوع,الجهة,الإدارة,الحالة",...rows.map(r=>[r.reference,r.type,r.priority,r.subject,r.entity,r.department,r.status].map(esc).join(","))].join("\n");return new Response("\ufeff"+csv,{headers:{"content-type":"text/csv; charset=utf-8","content-disposition":"attachment; filename=morasalat-report.csv"}})}
 return json({ok:false,error:"المسار غير موجود"},404)
}
export default{async fetch(req,env){const url=new URL(req.url),start=Date.now();try{const res=url.pathname.startsWith("/api/")?await api(req,env,url):await env.ASSETS.fetch(req);console.log(JSON.stringify({method:req.method,path:url.pathname,status:res.status,duration_ms:Date.now()-start}));return res}catch(error){console.error(JSON.stringify({method:req.method,path:url.pathname,error:String(error),duration_ms:Date.now()-start}));return json({ok:false,error:"تعذر تنفيذ الطلب",request_id:crypto.randomUUID()},500)}}};
